package app.oncare.personal;
import android.content.Context;
import android.util.AtomicFile;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
/** Extended backup compatibility; all fields remain data, never executable instructions. */
final class HealthArchive {
 static final Set<String> TYPES=new HashSet<>(Arrays.asList("ActiveCaloriesBurnedRecord","BasalBodyTemperatureRecord","BasalMetabolicRateRecord","BloodGlucoseRecord","BloodPressureRecord","BodyFatRecord","BodyTemperatureRecord","BodyWaterMassRecord","BoneMassRecord","CervicalMucusRecord","CyclingPedalingCadenceRecord","DistanceRecord","ElevationGainedRecord","ExerciseSessionRecord","FloorsClimbedRecord","HeartRateRecord","HeartRateVariabilityRmssdRecord","HeightRecord","HydrationRecord","IntermenstrualBleedingRecord","LeanBodyMassRecord","MenstruationFlowRecord","MenstruationPeriodRecord","NutritionRecord","OvulationTestRecord","OxygenSaturationRecord","PowerRecord","RespiratoryRateRecord","RestingHeartRateRecord","SexualActivityRecord","SleepSessionRecord","SpeedRecord","StepsCadenceRecord","StepsRecord","TotalCaloriesBurnedRecord","Vo2MaxRecord","WeightRecord","SkinTemperatureRecord","PlannedExerciseSessionRecord","MindfulnessSessionRecord","StateOfMindRecord","ActivityIntensityRecord", "WheelchairPushesRecord", "MedicalALLERGIES_INTOLERANCES", "MedicalCONDITIONS", "MedicalLABORATORY_RESULTS", "MedicalMEDICATIONS", "MedicalPERSONAL_DETAILS", "MedicalPRACTITIONER_DETAILS", "MedicalPREGNANCY", "MedicalPROCEDURES", "MedicalSOCIAL_HISTORY", "MedicalVACCINES", "MedicalVISITS", "MedicalVITAL_SIGNS"));
 static final Set<String> CATEGORIES=new HashSet<>(Arrays.asList("활동","신체","생체","영양","주기","수면","마음","의료"));
 static void fields(Object value,int depth,int[] nodes)throws JSONException{if(depth>12||++nodes[0]>100000)throw new JSONException("field limits");if(value instanceof JSONObject){JSONObject o=(JSONObject)value;Iterator<String> keys=o.keys();while(keys.hasNext()){String k=keys.next();if(k.length()>200)throw new JSONException("field key");fields(o.get(k),depth+1,nodes);}}else if(value instanceof JSONArray){JSONArray a=(JSONArray)value;for(int i=0;i<a.length();i++)fields(a.get(i),depth+1,nodes);}else if(value instanceof Number){if(!Double.isFinite(((Number)value).doubleValue()))throw new JSONException("field number");}else if(value instanceof String&&((String)value).length()>100000)throw new JSONException("field text");}
 static void validate(JSONObject data)throws JSONException{JSONArray records=data.optJSONArray("healthRecords"),availability=data.optJSONArray("healthAvailability");if(data.has("healthRecords")&&records==null||data.has("healthAvailability")&&availability==null)throw new JSONException("archive type");if(records!=null&&records.length()>10000||availability!=null&&availability.length()>TYPES.size())throw new JSONException("archive count");Set<String> ids=new HashSet<>();int[] nodes={0};for(int i=0;records!=null&&i<records.length();i++){JSONObject r=records.getJSONObject(i);String id=r.getString("id");if(!id.startsWith("hc:")||id.length()>100||!ids.add(id)||!TYPES.contains(r.getString("recordType"))||r.getLong("date")<=0||r.getLong("date")>System.currentTimeMillis()||r.getString("title").isEmpty()||r.getString("title").length()>100||!CATEGORIES.contains(r.getString("category"))||r.optString("source").length()>100)throw new JSONException("archive record");fields(r.getJSONObject("fields"),0,nodes);}Set<String> seen=new HashSet<>();for(int i=0;availability!=null&&i<availability.length();i++){JSONObject a=availability.getJSONObject(i);String type=a.getString("recordType"),status=a.getString("status");int count=a.getInt("count");if(!TYPES.contains(type)||!seen.add(type)||!CATEGORIES.contains(a.getString("category"))||a.getString("title").isEmpty()||a.getString("title").length()>100||!Arrays.asList("ready","empty","permission","unsupported","error").contains(status)||count<0||count>10000||!status.equals("ready")&&count!=0)throw new JSONException("availability");}JSONObject archive=new JSONObject();if(records!=null)archive.put("healthRecords",records);if(availability!=null)archive.put("healthAvailability",availability);if(archive.toString().getBytes(StandardCharsets.UTF_8).length>4*1024*1024)throw new JSONException("archive size");}
 static AtomicFile file(Context c){return new AtomicFile(new File(c.getFilesDir(),"health-archive-v1.json"));}
 static JSONObject load(Context c)throws Exception{AtomicFile file=file(c);if(!file.getBaseFile().exists()&&!new File(file.getBaseFile()+".bak").exists())return new JSONObject();try(InputStream input=file.openRead()){ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] buffer=new byte[4096];int n;while((n=input.read(buffer))!=-1){bytes.write(buffer,0,n);if(bytes.size()>4*1024*1024)throw new IOException("archive size");}JSONObject data=new JSONObject(bytes.toString("UTF-8"));validate(data);return data;}}
 static void save(Context c,JSONObject data)throws Exception{validate(data);AtomicFile file=file(c);FileOutputStream output=null;try{output=file.startWrite();output.write(data.toString().getBytes(StandardCharsets.UTF_8));file.finishWrite(output);}catch(Exception e){if(output!=null)file.failWrite(output);throw e;}}
 static JSONObject merge(JSONObject old,JSONObject next)throws Exception{validate(next);JSONObject out=new JSONObject(old.toString());if(next.has("healthRecords")){JSONArray records=new JSONArray();Set<String> ids=new HashSet<>();for(JSONObject input:new JSONObject[]{old,next}){JSONArray list=input.optJSONArray("healthRecords");for(int i=0;list!=null&&i<list.length();i++){JSONObject r=list.getJSONObject(i);if(ids.add(r.getString("id")))records.put(r);}}out.put("healthRecords",records);}if(next.has("healthAvailability"))out.put("healthAvailability",next.getJSONArray("healthAvailability"));validate(out);return out;}
}
